/**
 * One catalog an installed add-on offers, presented as a Discover source.
 *
 * Holds the add-on rather than just its id because paging a catalog needs the whole record (a
 * local add-on is fetched straight from the device, a hosted one through its transport URL).
 */
private data class AddonDiscoverSource(
  val key: String,
  val addon: InstalledAddon,
  val catalog: AddonCatalog,
  /** "Add-on · Catalog", for the picker where there is room to disambiguate two add-ons that
   * both call a catalog something generic like "Search". */
  val label: String,
  /** Just the catalog name, for the filter row. The full label is far too long there - it
   * ellipsised to "Xperience · To…", which told the user nothing about what was selected. */
  val shortLabel: String,
)

/** Section heading for playlist results, with a count so a capped list does not look like the
 * whole answer. */
@Composable
private fun PlaylistResultsHeader(title: String, count: Int) {
  Column(
    modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 6.dp),
    verticalArrangement = Arrangement.spacedBy(2.dp),
  ) {
    Text(title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onBackground)
    Text(
      if (count >= PLAYLIST_SEARCH_LIMIT) "Top $count matches" else "$count ${if (count == 1) "match" else "matches"}",
      style = MaterialTheme.typography.bodySmall,
      color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.58f),
    )
  }
}

/** How many playlist matches one section will show. A provider list can match thousands of
 * entries for a short query, and past a screenful the rest is noise. */
internal const val PLAYLIST_SEARCH_LIMIT = 60

/**
 * True when [needle] starts a word in this string.
 *
 * Uses case-insensitive indexOf rather than lowercasing, because this runs once per playlist entry
 * per keystroke and a 200k-entry list would otherwise allocate 200k throwaway strings each time.
 */
internal fun String.containsWordStart(needle: String): Boolean {
  var index = indexOf(needle, ignoreCase = true)
  while (index >= 0) {
    if (index == 0 || !this[index - 1].isLetterOrDigit()) return true
    index = indexOf(needle, index + 1, ignoreCase = true)
  }
  return false
}

/**
 * How well a playlist entry answers [needle], lower being better, or null when it does not.
 *
 * Ranked by *how* the match was made rather than by position alone, so searching "bbc" puts the
 * channel called "BBC One" above a film whose category merely happens to mention it.
 */
internal fun MediaItem.playlistSearchRank(needle: String): Int? = when {
  title.equals(needle, ignoreCase = true) -> 0
  title.startsWith(needle, ignoreCase = true) -> 1
  title.containsWordStart(needle) -> 2
  title.contains(needle, ignoreCase = true) -> 3
  sourceCatalogName?.contains(needle, ignoreCase = true) == true -> 4
  else -> null
}

/**
 * The best [limit] entries for [query], already ordered.
 *
 * Deliberately searches the title and category only. Playlist descriptions are built from the
 * group and source name, so matching them too would make almost every entry in a category match
 * any word from its name.
 */
internal fun List<MediaItem>.matchingPlaylistItems(query: String, limit: Int = PLAYLIST_SEARCH_LIMIT): List<MediaItem> {
  val needle = query.trim()
  if (needle.length < 2) return emptyList()
  val ranked = ArrayList<Pair<Int, MediaItem>>()
  for (item in this) {
    val rank = item.playlistSearchRank(needle) ?: continue
    ranked.add(rank to item)
  }
  return ranked
    .sortedWith(compareBy({ it.first }, { it.second.title.lowercase() }))
    .take(limit)
    .map { it.second }
}

private fun List<MediaItem>.filteredBy(filter: MediaFilter): List<MediaItem> = when (filter) {
  MediaFilter.All -> this
  MediaFilter.Movies -> filter { it.type == "movie" }
  MediaFilter.Series -> filter { it.type == "tv" || it.type == "series" }
}

@Composable
private fun LibraryEmptyState(icon: @Composable () -> Unit, title: String, subtitle: String) {
  Box(modifier = Modifier.fillMaxWidth().height(520.dp), contentAlignment = Alignment.Center) {
    Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(18.dp), modifier = Modifier.padding(horizontal = 28.dp)) {
      Box(
        modifier = Modifier.size(96.dp).clip(CircleShape).background(MaterialTheme.colorScheme.onBackground.copy(alpha = 0.055f)).border(1.dp, MaterialTheme.colorScheme.onBackground.copy(alpha = 0.10f), CircleShape),
        contentAlignment = Alignment.Center,
      ) { icon() }
      Text(title, style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Black, color = MaterialTheme.colorScheme.onBackground)
      Text(subtitle, style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onBackground.copy(alpha = 0.72f), textAlign = androidx.compose.ui.text.style.TextAlign.Center)
    }
  }
}

@Composable
private fun MediaCardActionsDialog(
  item: MediaItem,
  inWatchlist: Boolean,
  includeRemoveAction: Boolean,
  onAddToWatchlist: () -> Unit,
  onRemoveFromWatchlist: () -> Unit,
  onMarkWatched: () -> Unit,
  onDismiss: () -> Unit,
) {
  val context = LocalContext.current
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false)) {
    CardActionsAmbientScaffold(item = item, onDismiss = onDismiss) {
      if (!inWatchlist || !includeRemoveAction) {
        AmbientActionRow("Add to Watchlist", icon = Icons.Rounded.Bookmark) {
          if (!inWatchlist) onAddToWatchlist()
          onDismiss()
        }
      }
      if (includeRemoveAction && inWatchlist) {
        AmbientActionRow("Remove from Watchlist", icon = Icons.Rounded.Close) {
          onRemoveFromWatchlist()
          onDismiss()
        }
      }
      AmbientActionRow("Mark as Watched", icon = Icons.Rounded.CheckCircle) {
        onMarkWatched()
        onDismiss()
      }
      AmbientActionRow("Share", icon = Icons.Rounded.Share) {
        val shareIntent = Intent(Intent.ACTION_SEND).apply {
          type = "text/plain"
          putExtra(Intent.EXTRA_TEXT, item.title)
        }
        context.startActivity(Intent.createChooser(shareIntent, item.title))
        onDismiss()
      }
    }
  }
}

@Composable
private fun ContinueWatchingActionsDialog(
  item: MediaItem,
  inWatchlist: Boolean,
  onRestartFromBeginning: () -> Unit,
  onOpenDetails: () -> Unit,
  onAddToWatchlist: () -> Unit,
  onMarkWatched: () -> Unit,
  onDismiss: () -> Unit,
  handoffDevices: List<LinkedTvDevice> = emptyList(),
  onRefreshHandoffDevices: () -> Unit = {},
  onHandoffToTv: (suspend (LinkedTvDevice) -> Result<PlaybackHandoffReceipt>)? = null,
) {
  val context = LocalContext.current
  var choosingTv by remember(item.id) { mutableStateOf(false) }
  Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false)) {
    CardActionsAmbientScaffold(item = item, onDismiss = onDismiss) {
      if (choosingTv && onHandoffToTv != null) {
        TvHandoffPicker(
          item = item,
          devices = handoffDevices,
          onRefreshDevices = onRefreshHandoffDevices,
          onHandoff = onHandoffToTv,
          onBack = { choosingTv = false },
          onDismiss = onDismiss,
        )
        return@CardActionsAmbientScaffold
      }
      AmbientActionRow("Restart from Beginning", icon = Icons.Rounded.Replay) {
        onDismiss()
        onRestartFromBeginning()
      }
      if (onHandoffToTv != null) {
        AmbientActionRow("Watch on StreamDek TV", icon = Icons.Rounded.Tv) {
          onRefreshHandoffDevices()
          choosingTv = true
        }
      }
      AmbientActionRow("Details", icon = Icons.Rounded.Info) {
        onDismiss()
        onOpenDetails()
      }
      if (!inWatchlist) {
        AmbientActionRow("Add to Watchlist", icon = Icons.Rounded.Bookmark) {
          onAddToWatchlist()
          onDismiss()
        }
      }
      AmbientActionRow("Mark as Watched", icon = Icons.Rounded.CheckCircle) {
        onMarkWatched()
        onDismiss()
      }
      AmbientActionRow("Share", icon = Icons.Rounded.Share) {
        val shareIntent = Intent(Intent.ACTION_SEND).apply {
          type = "text/plain"
          putExtra(Intent.EXTRA_TEXT, item.title)
        }
        context.startActivity(Intent.createChooser(shareIntent, item.title))
        onDismiss()
      }
    }
  }
}

/**
 * The "choose a TV" step shared by the live-channel and continue-watching long-press menus.
 * Rendered inline inside [CardActionsAmbientScaffold] rather than as its own dialog so the
 * ambient artwork stays put while the action list swaps to the device list.
 */
@Composable
private fun ColumnScope.TvHandoffPicker(
  item: MediaItem,
  devices: List<LinkedTvDevice>,
  onRefreshDevices: () -> Unit,
  onHandoff: suspend (LinkedTvDevice) -> Result<PlaybackHandoffReceipt>,
  onBack: () -> Unit,
  onDismiss: () -> Unit,
) {
  val scope = rememberCoroutineScope()
  var sendingDeviceId by remember(item.id) { mutableStateOf<String?>(null) }
  var statusMessage by remember(item.id) { mutableStateOf<String?>(null) }
  Text("Choose a StreamDek TV", color = Color.White, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Black, modifier = Modifier.padding(horizontal = 22.dp, vertical = 8.dp))
  statusMessage?.let { message ->
    Text(message, color = Color.White.copy(alpha = 0.78f), style = MaterialTheme.typography.bodyMedium, modifier = Modifier.padding(horizontal = 22.dp, vertical = 4.dp))
  }
  if (devices.isEmpty()) {
    Text("No linked TV is available yet. Make sure StreamDek TV is signed in and online.", color = Color.White.copy(alpha = 0.72f), modifier = Modifier.padding(horizontal = 22.dp, vertical = 8.dp))
    AmbientActionRow("Refresh TVs", icon = Icons.Rounded.Refresh) { onRefreshDevices() }
  } else {
    devices.forEach { device ->
      AmbientActionRow(if (sendingDeviceId == device.id) "Sending to ${device.name}…" else device.name, icon = Icons.Rounded.Tv) {
        if (sendingDeviceId == null) {
          sendingDeviceId = device.id
          statusMessage = "Preparing ${item.title} securely…"
          scope.launch {
            onHandoff(device)
              .onSuccess {
                statusMessage = "Sent to ${device.name}. Accept the prompt on your TV."
                delay(900)
                onDismiss()
              }
              .onFailure { error ->
                sendingDeviceId = null
                statusMessage = error.message ?: "This title could not be sent. Please try again."
              }
          }
        }
      }
    }
  }
  AmbientActionRow("Back", icon = Icons.Rounded.Close) { statusMessage = null; onBack() }
}
@Composable
private fun LiveChannelActionsDialog(
  item: MediaItem,
  isFavourite: Boolean,
  devices: List<LinkedTvDevice>,
  onToggleFavourite: () -> Unit,
  onRefreshDevices: () -> Unit,
