    Box(
      modifier = Modifier.size(38.dp).clip(CircleShape).background(MaterialTheme.colorScheme.primary.copy(alpha = 0.13f)).border(1.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.34f), CircleShape),
