    detail.year?.let { "Year" to it },
    detail.runtimeMinutes?.let { "Runtime" to "${it} min" },
    detail.seasonsCount?.takeIf { detail.type == "tv" }?.let { "Seasons" to "$it" },
    detail.rating?.let { "Rating" to "${"%.1f".format(it)}/10" },
